// Nitro OTA wiring for the generated MainApplication.kt, mirroring Apex's hand-written one (which this repo can't
// keep, because android/ is regenerated by `expo prebuild --clean`). Replaces react-native-nitro-ota's own config
// plugin (deliberately NOT listed in app.json): that one hands the stored bundle path to React Native unchecked.
//
// On every cold start:
//  1. Nitro's CrashHandler is installed (crash right after an update -> automatic rollback).
//  2. If the APK changed since the last start (versionName|versionCode|lastUpdateTime), all OTA data is dropped:
//     a bundle never outlives the native build it was made for.
//  3. The stored bundle must exist AND pass OtaVerifier.check (pc-native): signed by the laptop's OTA key, built
//     for this exact versionName+versionCode, every file hash matching. Otherwise the OTA data is cleared, a
//     recovery note is written for Settings, and the JS embedded in the APK runs.
const { withMainApplication } = require('expo/config-plugins');

const FIELDS = `
  private val nitroOtaPreferencesSuiteName = "NitroOtaPrefs"
  private val nitroOtaBinaryFingerprintKey = "pccontrol_nitro_ota_last_seen_binary_fingerprint"
`;

const METHODS = `
  private fun getSafeNitroOtaBundlePath(): String? {
    CrashHandler.install(this)
    val sharedPreferences = getSharedPreferences(nitroOtaPreferencesSuiteName, MODE_PRIVATE)
    resetNitroOtaForBinaryChangeIfNeeded(sharedPreferences)
    val preferences = PreferencesUtils.create(this)
    val storedPath = preferences.getOtaUnzippedPath()
    if (storedPath.isNullOrEmpty()) return null
    if (!File(storedPath).isFile) {
      rejectNitroOtaBundle(preferences, storedPath, "missing_bundle_file",
        "A downloaded update could not be loaded, so the app went back to the version built into the APK.")
      return null
    }
    val problem = OtaVerifier.check(this, storedPath)
    if (problem != null) {
      rejectNitroOtaBundle(preferences, storedPath, "rejected_bundle",
        "A downloaded update was refused ($problem), so the app went back to the version built into the APK.")
      return null
    }
    return storedPath
  }

  private fun resetNitroOtaForBinaryChangeIfNeeded(sharedPreferences: SharedPreferences) {
    val current = try {
      val pi = packageManager.getPackageInfo(packageName, 0)
      val code = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) pi.longVersionCode else {
        @Suppress("DEPRECATION") pi.versionCode.toLong()
      }
      "\${pi.versionName}|$code|\${pi.lastUpdateTime}"
    } catch (_: PackageManager.NameNotFoundException) { "unknown" }
    if (sharedPreferences.getString(nitroOtaBinaryFingerprintKey, null) == current) return
    clearNitroOtaPreferenceKeys(sharedPreferences)
    deleteNitroOtaDirs()
    sharedPreferences.edit().putString(nitroOtaBinaryFingerprintKey, current).apply()
  }

  private fun clearNitroOtaPreferenceKeys(sharedPreferences: SharedPreferences) {
    val prefixes = listOf("ota_unzipped_path_", "ota_version_", "ota_update_download_url_",
      "ota_update_version_check_url_", "ota_bundle_name_", "ota_previous_unzipped_path_", "ota_previous_version_",
      "ota_rollback_count_", "ota_blacklisted_versions_", "ota_rollback_history_", "ota_pending_validation_",
      "ota_notified_rollback_count_")
    val editor = sharedPreferences.edit()
    sharedPreferences.all.keys.filter { k -> prefixes.any(k::startsWith) }.forEach(editor::remove)
    editor.apply()
  }

  private fun deleteNitroOtaDirs() {
    try {
      (filesDir.listFiles { f -> f.isDirectory && f.name.startsWith("ota_unzipped_") } ?: emptyArray())
        .forEach { runCatching { it.deleteRecursively() } }
    } catch (_: Exception) {}
  }

  private fun rejectNitroOtaBundle(preferences: PreferencesUtils, path: String, reason: String, message: String) {
    try {
      OtaVerifier.recoveryFile(this).writeText(JSONObject()
        .put("reason", reason)
        .put("message", message)
        .put("otaVersion", preferences.getOtaVersion() ?: JSONObject.NULL)
        .put("previousOtaVersion", preferences.getPreviousVersion() ?: JSONObject.NULL)
        .put("bundleName", File(path).name)
        .put("detectedAtMs", System.currentTimeMillis()).toString())
    } catch (_: Exception) {}
    try { preferences.clearOtaData() } catch (_: Exception) {}
    deleteNitroOtaDirs()
  }
`;

const IMPORTS = [
  'import android.content.SharedPreferences',
  'import android.content.pm.PackageManager',
  'import android.os.Build',
  'import java.io.File',
  'import org.json.JSONObject',
  'import com.margelo.nitro.nitroota.utils.CrashHandler',
  'import com.margelo.nitro.nitroota.utils.PreferencesUtils',
  'import expo.modules.pcnative.OtaVerifier',
];

module.exports = function withNitroOta(config) {
  return withMainApplication(config, (cfg) => {
    let s = cfg.modResults.contents;
    if (s.includes('getSafeNitroOtaBundlePath')) return cfg;
    const must = (re, what) => {
      if (!re.test(s)) throw new Error(`withNitroOta: could not find ${what} in MainApplication.kt`);
    };
    must(/import android\.app\.Application\n/, 'the Application import');
    s = s.replace(/import android\.app\.Application\n/, (m) => m + IMPORTS.join('\n') + '\n');
    must(/class MainApplication : Application\(\), ReactApplication \{\n/, 'the class header');
    s = s.replace(/class MainApplication : Application\(\), ReactApplication \{\n/, (m) => m + FIELDS);
    const pkg = /(PackageList\(this\)\.packages\.apply \{[\s\S]*?\n\s*\})(\s*\n\s*\))/;
    must(pkg, 'the getDefaultReactHost packageList');
    s = s.replace(pkg, '$1,\n      jsBundleFilePath = getSafeNitroOtaBundlePath()$2');
    s = s.replace(/\n\}\s*$/, '\n' + METHODS + '}\n');
    cfg.modResults.contents = s;
    return cfg;
  });
};
